new = '''def optimum(job, active, pairs, limit=400000):
    """Brute-force maximum cardinality / minimum cost over tiny instances."""
    table = {r['id']: r for r in job['requests']}
    offers = {o['id']: o for o in job['offers']}
    rq = {q['id']: q for q in job['request_quotas']}
    oq = {q['id']: q for q in job['offer_quotas']}

    def ancestors(node, table_):
        chain = []
        while node is not None:
            chain.append(node)
            node = table_[node]['parent']
        return chain

    requests = [r for r in sorted(active) if active[r]]
    options = {r: sorted(o for (x, o) in pairs if x == r) for r in requests}
    requests = [r for r in requests if options[r]]
    branches = 1
    for r in requests:
        branches *= (len(options[r]) + 1)
    if branches > limit:
        return None
    best = None
    counts = collections.Counter()

    def walk(index, chosen, cost):
        nonlocal best
        if index == len(requests):
            key = (-len(chosen), cost)
            if best is None or key < best[0]:
                best = (key, dict(chosen))
            return
        request = requests[index]
        walk(index + 1, chosen, cost)
        for offer in options[request]:
            node_ok = True
            for node in ancestors(table[request]['group'], rq):
                counts[('r', node)] += 1
                if counts[('r', node)] > rq[node]['capacity']:
                    node_ok = False
            for node in ancestors(offers[offer]['group'], oq):
                counts[('o', node)] += 1
                if counts[('o', node)] > oq[node]['capacity']:
                    node_ok = False
            if counts[('x', offer)] >= offers[offer]['capacity']:
                node_ok = False
            counts[('x', offer)] += 1
            if node_ok:
                chosen[request] = offer
                walk(index + 1, chosen, cost + offers[offer]['cost'])
                del chosen[request]
            counts[('x', offer)] -= 1
            for node in ancestors(table[request]['group'], rq):
                counts[('r', node)] -= 1
            for node in ancestors(offers[offer]['group'], oq):
                counts[('o', node)] -= 1
    walk(0, {}, 0)
    return best


'''
